reference_solution:
def searchInsert(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

brute_force_solution:
def searchInsert(nums, target):
    for i, x in enumerate(nums):
        if x >= target:
            return i
    return len(nums)

